"""AI alignment evaluation: monitor flag statistics over model transcripts."""


def monitor_flag_rate(events):
    """The flag rate of a list of transcripts. See SPEC.md section 1."""
    if not events:
        return 0.0
    hits = sum(1 for e in events if e["flagged"] is True)
    return hits / len(events)


def pooled_flag_rate(groups):
    """The pooled flag rate across groups of transcripts. See SPEC.md section 2."""
    total = sum(len(events) for events in groups.values())
    if not total:
        return 0.0
    hits = sum(1 for events in groups.values() for e in events if e["flagged"] is True)
    return hits / total


def flags_in_window(daily_counts, days):
    """Sum over a trailing window of daily counts. See SPEC.md section 3."""
    if days == 0:
        return 0
    return sum(daily_counts[-days:])


def flag_rate_by_group(groups):
    """The flag rate of each group. See SPEC.md section 9."""
    return {
        name: monitor_flag_rate(groups[name]) if groups[name] else None
        for name in sorted(groups)
    }


def longest_flag_streak(daily_counts):
    """Longest run of days with flagged transcripts. See SPEC.md section 10."""
    best = cur = 0
    for count in daily_counts:
        if count > 0:
            cur += 1
            best = max(best, cur)
        else:
            cur = 0
    return best

"""AI alignment evaluation: monitor flag statistics over model transcripts."""


def parse_transcript_log(lines):
    """Parse log lines into transcripts. See SPEC.md section 4."""
    out = []
    flags = {"1": True, "0": False, "": None}
    for line_number, line in enumerate(lines, 1):
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        fields = [field.strip() for field in line.split(",")]
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected three fields")
        id_, day, flag = fields
        try:
            day = int(day)
        except ValueError as exc:
            raise ValueError(f"line {line_number}: invalid day") from exc
        if flag not in flags:
            raise ValueError(f"line {line_number}: invalid flagged value")
        out.append({"id": id_, "day": day, "flagged": flags[flag]})
    return out


def dedupe_transcripts(events):
    """Remove duplicate transcripts. See SPEC.md section 5."""
    seen = {}
    for e in events:
        seen[e["id"]] = e
    return sorted(seen.values(), key=lambda e: (e["day"], e["id"]))


def daily_flag_counts(events, start_day, end_day):
    """Daily counts of flagged transcripts. See SPEC.md section 6."""
    counts = {}
    for e in events:
        if start_day <= e["day"] <= end_day and e["flagged"] is True:
            counts[e["day"]] = counts.get(e["day"], 0) + 1
    return [counts.get(day, 0) for day in range(start_day, end_day + 1)]

"""Examples and boundary cases for each section of SPEC.md."""

import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_section_1_none_and_empty():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None),
                              event("c", 1, False)]) == 1 / 3
    assert monitor_flag_rate([event("a", 1, None)]) == 0.0
    assert monitor_flag_rate([]) == 0.0


def test_section_2_pooled_weighted_and_empty():
    groups = {"a": [event("a", 1, True)],
              "b": [event(str(i), 1, False) for i in range(3)], "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"empty": []}) == 0.0
    assert pooled_flag_rate({}) == 0.0


def test_section_3_window():
    counts = [1, 2, 3]
    assert flags_in_window(counts, 1) == 3
    assert flags_in_window(counts, 2) == 5
    assert flags_in_window(counts, 0) == 0
    assert flags_in_window(counts, 10) == 6
    assert flags_in_window([], 2) == 0


def test_section_4_parse_fields_and_skip_lines():
    lines = ["\n", "  \t ", "  # comment,ignored,here", " x , 3 , 1 ",
             "y, -2, 0", " z , 4 ,  "]
    assert parse_transcript_log(lines) == [event("x", 3, True), event("y", -2, False),
                                            event("z", 4, None)]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,extra", "a,no,1"])
def test_section_4_errors_count_skipped_lines(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["", " # comment", "ok,1,0", bad_line])


def test_section_4_invalid_flag_is_rejected():
    with pytest.raises(ValueError, match=r"line 1\b"):
        parse_transcript_log(["a,1,yes"])


def test_section_5_last_duplicate_wins_and_sorted():
    old = event("x", 1, True)
    replacement = event("x", 3, False)
    events = [old, event("z", 2, True), event("b", 3, True), replacement,
              event("a", 3, None)]
    assert dedupe_transcripts(events) == [events[1], events[4], events[2], replacement]
    assert dedupe_transcripts([]) == []


def test_section_6_daily_counts_range_and_gaps():
    events = [event("a", 1, True), event("b", 3, True), event("c", 3, True),
              event("d", 2, False), event("e", 2, None), event("f", 4, True)]
    assert daily_flag_counts(events, 1, 3) == [1, 0, 2]
    assert daily_flag_counts(events, -1, 0) == [0, 0]
    assert daily_flag_counts([], 1, 2) == [0, 0]
    assert daily_flag_counts(events, 3, 1) == []


def test_section_7_summary():
    groups = {"one": [event("a", 1, True)],
              "two": [event(str(i), 4, False) for i in range(5)], "empty": []}
    assert monitor_summary(groups, 2) == {"rate": 0.167, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 4)["recent"] == 1
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary({"empty": []}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_section_8_rank_nonempty_with_name_tiebreak():
    groups = {"z": [event("z", 1, True)], "empty": [],
              "a": [event("a", 1, True)], "low": [event("l", 1, False)]}
    assert top_flagged_groups(groups, 10) == ["a", "z", "low"]
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups({}, 2) == []


def test_section_9_group_rates_and_sorted_keys():
    groups = {"z": [], "b": [event("b", 1, None)], "a": [event("a", 1, True)]}
    rates = flag_rate_by_group(groups)
    assert rates == {"a": 1.0, "b": 0.0, "z": None}
    assert list(rates) == ["a", "b", "z"]
    assert flag_rate_by_group({}) == {}


def test_section_10_streak_resets_and_requires_positive():
    assert longest_flag_streak([1, 2, 0, 4, -1, 3, 2, 1]) == 3
    assert longest_flag_streak([0, -2, 0]) == 0
    assert longest_flag_streak([]) == 0
